CREATE TABLE mate_semantic_ontology(id VARCHAR(36) PRIMARY KEY,workspace_id BIGINT NOT NULL,name VARCHAR(128),description VARCHAR(1000),latest_version INT,latest_revision_id VARCHAR(36),draft_id VARCHAR(36),draft_counter BIGINT,updated_at TIMESTAMP);
CREATE TABLE mate_semantic_ontology_revision(id VARCHAR(36) PRIMARY KEY,ontology_id VARCHAR(36) NOT NULL,version INT,draft_version BIGINT,revision_state VARCHAR(16),draft_slot INT,name VARCHAR(128),description VARCHAR(1000),definition_json TEXT,base_revision_id VARCHAR(36),available_for_new_bindings BOOLEAN,published_at TIMESTAMP,published_by VARCHAR(32),publication_note VARCHAR(1000),document_text TEXT,document_syntax VARCHAR(32),document_digest VARCHAR(64),ontology_iri VARCHAR(2048),version_iri VARCHAR(2048),import_lock_digest VARCHAR(64),model_schema VARCHAR(32),imports_json TEXT,policy_json TEXT,FOREIGN KEY(ontology_id) REFERENCES mate_semantic_ontology(id));
CREATE TABLE mate_semantic_graph(id VARCHAR(36) PRIMARY KEY,workspace_id BIGINT,kb_id BIGINT,ontology_revision_id VARCHAR(36),enabled BOOLEAN,mutation_version BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP,FOREIGN KEY(ontology_revision_id) REFERENCES mate_semantic_ontology_revision(id));
CREATE TABLE mate_semantic_entity(id VARCHAR(36) PRIMARY KEY,graph_id VARCHAR(36),type_key VARCHAR(128),iri VARCHAR(2048),asserted_types_json TEXT,FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_ontology_axiom(revision_id VARCHAR(36),axiom_id VARCHAR(64),axiom_kind VARCHAR(64),axiom_text TEXT,signature_json TEXT,PRIMARY KEY(revision_id,axiom_id),FOREIGN KEY(revision_id) REFERENCES mate_semantic_ontology_revision(id));
CREATE TABLE mate_semantic_ontology_source_snapshot(id VARCHAR(36) PRIMARY KEY,workspace_id BIGINT,kb_id BIGINT,source_ref VARCHAR(32),source_title VARCHAR(512),source_text TEXT,source_digest VARCHAR(64),captured_by VARCHAR(32),captured_at TIMESTAMP);
CREATE TABLE mate_semantic_axiom_source(id VARCHAR(36) PRIMARY KEY,revision_id VARCHAR(36),axiom_id VARCHAR(64),source_snapshot_id VARCHAR(36),source_digest VARCHAR(64),exact_quote TEXT,start_code_point INT,end_code_point INT,origin VARCHAR(24),review_state VARCHAR(24),created_by VARCHAR(32),created_at TIMESTAMP,FOREIGN KEY(revision_id,axiom_id) REFERENCES mate_semantic_ontology_axiom(revision_id,axiom_id),FOREIGN KEY(source_snapshot_id) REFERENCES mate_semantic_ontology_source_snapshot(id));
CREATE TABLE mate_semantic_ontology_source_review(id VARCHAR(36) PRIMARY KEY,binding_id VARCHAR(36),observed_digest VARCHAR(64),source_state VARCHAR(24),review_state VARCHAR(24),decision VARCHAR(24),reason TEXT,observed_snapshot_id VARCHAR(36),FOREIGN KEY(binding_id) REFERENCES mate_semantic_axiom_source(id),FOREIGN KEY(observed_snapshot_id) REFERENCES mate_semantic_ontology_source_snapshot(id));
CREATE TABLE mate_semantic_source_snapshot(id VARCHAR(36) PRIMARY KEY,graph_id VARCHAR(36),text_content TEXT,FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_import_job(id VARCHAR(36) PRIMARY KEY,graph_id VARCHAR(36),snapshot_id VARCHAR(36),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_evidence(id VARCHAR(36) PRIMARY KEY,graph_id VARCHAR(36),snapshot_id VARCHAR(36),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id),FOREIGN KEY(snapshot_id) REFERENCES mate_semantic_source_snapshot(id));
CREATE TABLE mate_semantic_statement(id VARCHAR(36) PRIMARY KEY,graph_id VARCHAR(36),current_revision INT,FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_statement_revision(statement_id VARCHAR(36),revision INT,graph_id VARCHAR(36),ontology_revision_id VARCHAR(36),subject_id VARCHAR(36),content_json TEXT,PRIMARY KEY(statement_id,revision),FOREIGN KEY(statement_id) REFERENCES mate_semantic_statement(id),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_revision_evidence(statement_id VARCHAR(36),revision INT,evidence_id VARCHAR(36),PRIMARY KEY(statement_id,revision,evidence_id),FOREIGN KEY(statement_id,revision) REFERENCES mate_semantic_statement_revision(statement_id,revision),FOREIGN KEY(evidence_id) REFERENCES mate_semantic_evidence(id));
CREATE TABLE mate_semantic_change_proposal(id VARCHAR(36) PRIMARY KEY,graph_id VARCHAR(36),target_statement_id VARCHAR(36),payload_json TEXT,FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_conflict(id VARCHAR(36) PRIMARY KEY,graph_id VARCHAR(36),left_statement_id VARCHAR(36),right_statement_id VARCHAR(36),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_source_governance(graph_id VARCHAR(36),source_id VARCHAR(64),state VARCHAR(16),PRIMARY KEY(graph_id,source_id),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_snapshot_exclusion(graph_id VARCHAR(36),snapshot_id VARCHAR(36),PRIMARY KEY(graph_id,snapshot_id),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_mutation_command(id VARCHAR(36) PRIMARY KEY,graph_id VARCHAR(36),result_json TEXT,FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_governance_event(id VARCHAR(36) PRIMARY KEY,workspace_id BIGINT,graph_id VARCHAR(36),resource_id VARCHAR(128),result_json TEXT,FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_command_record(id VARCHAR(36) PRIMARY KEY,workspace_id BIGINT,resource_id VARCHAR(36),result_json TEXT);
CREATE TABLE mate_semantic_governance_record(id VARCHAR(36) PRIMARY KEY,workspace_id BIGINT,ontology_id VARCHAR(36),revision_id VARCHAR(36),detail_json TEXT);
CREATE TABLE mate_semantic_import_artifact(id VARCHAR(36) PRIMARY KEY,workspace_id BIGINT,document_digest VARCHAR(64),document_syntax VARCHAR(32),document_text TEXT);
CREATE TABLE mate_semantic_extraction_gate(id INT PRIMARY KEY);
CREATE TABLE mate_semantic_extraction_task(id VARCHAR(36) PRIMARY KEY,workspace_id VARCHAR(32),graph_id VARCHAR(36),generation BIGINT,FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_extraction_attempt(id VARCHAR(36) PRIMARY KEY,task_id VARCHAR(36),FOREIGN KEY(task_id) REFERENCES mate_semantic_extraction_task(id));
CREATE TABLE mate_semantic_extraction_suggestion(id VARCHAR(36) PRIMARY KEY,task_id VARCHAR(36),attempt_id VARCHAR(36),FOREIGN KEY(task_id) REFERENCES mate_semantic_extraction_task(id),FOREIGN KEY(attempt_id) REFERENCES mate_semantic_extraction_attempt(id));
CREATE TABLE mate_semantic_extraction_edit(suggestion_id VARCHAR(36),version BIGINT,payload_json TEXT,PRIMARY KEY(suggestion_id,version),FOREIGN KEY(suggestion_id) REFERENCES mate_semantic_extraction_suggestion(id));
CREATE TABLE mate_semantic_extraction_receipt(suggestion_id VARCHAR(36),edit_version BIGINT,graph_id VARCHAR(36),PRIMARY KEY(suggestion_id,edit_version),FOREIGN KEY(suggestion_id,edit_version) REFERENCES mate_semantic_extraction_edit(suggestion_id,version),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_extraction_submission_intent(suggestion_id VARCHAR(36),edit_version BIGINT,graph_id VARCHAR(36),PRIMARY KEY(suggestion_id,edit_version),FOREIGN KEY(suggestion_id,edit_version) REFERENCES mate_semantic_extraction_edit(suggestion_id,version),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_extraction_action(graph_id VARCHAR(36),operation_id VARCHAR(128),resource_id VARCHAR(36),PRIMARY KEY(graph_id,operation_id),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_wiki_knowledge_base(id BIGINT PRIMARY KEY,workspace_id BIGINT,name VARCHAR(128));
CREATE TABLE mate_wiki_raw_material(id BIGINT PRIMARY KEY,kb_id BIGINT,title VARCHAR(256),original_content TEXT);
CREATE TABLE mate_wiki_page(id BIGINT PRIMARY KEY,kb_id BIGINT,title VARCHAR(256),content TEXT);
CREATE TABLE mate_semantic_source_change_run(id VARCHAR(36) PRIMARY KEY,graph_id VARCHAR(36) NOT NULL,operation_id VARCHAR(128) NOT NULL,status VARCHAR(16) NOT NULL,expected_graph_version BIGINT,request_digest VARCHAR(64) NOT NULL,baseline_json TEXT NOT NULL,created_by VARCHAR(32) NOT NULL,created_at TIMESTAMP,updated_at TIMESTAMP,UNIQUE(graph_id,operation_id),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_source_change_lock(graph_id VARCHAR(36) NOT NULL,source_kind VARCHAR(24) NOT NULL,source_ref VARCHAR(64) NOT NULL,touched_at TIMESTAMP,PRIMARY KEY(graph_id,source_kind,source_ref),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_source_change(id VARCHAR(36) PRIMARY KEY,run_id VARCHAR(36) NOT NULL,graph_id VARCHAR(36) NOT NULL,source_kind VARCHAR(24) NOT NULL,source_ref VARCHAR(64) NOT NULL,old_snapshot_id VARCHAR(36),new_snapshot_id VARCHAR(36),old_digest VARCHAR(64),new_digest VARCHAR(64) NOT NULL,source_state VARCHAR(24) NOT NULL,observed_graph_version BIGINT NOT NULL,created_by VARCHAR(32) NOT NULL,created_at TIMESTAMP,UNIQUE(run_id,source_kind,source_ref),FOREIGN KEY(run_id) REFERENCES mate_semantic_source_change_run(id),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_source_change_item(id VARCHAR(36) PRIMARY KEY,change_id VARCHAR(36) NOT NULL,graph_id VARCHAR(36) NOT NULL,source_kind VARCHAR(24) NOT NULL,source_ref VARCHAR(64) NOT NULL,item_kind VARCHAR(24) NOT NULL,item_id VARCHAR(36) NOT NULL,item_revision BIGINT,old_snapshot_id VARCHAR(36),new_snapshot_id VARCHAR(36),old_digest VARCHAR(64),new_digest VARCHAR(64) NOT NULL,source_state VARCHAR(24) NOT NULL,review_state VARCHAR(16) NOT NULL,decision VARCHAR(24),reason VARCHAR(2000),decision_operation_id VARCHAR(128),observed_graph_version BIGINT NOT NULL,created_by VARCHAR(32) NOT NULL,created_at TIMESTAMP,reviewed_by VARCHAR(32),reviewed_at TIMESTAMP,UNIQUE(change_id,item_kind,item_id,item_revision,old_snapshot_id),FOREIGN KEY(change_id) REFERENCES mate_semantic_source_change(id),FOREIGN KEY(graph_id) REFERENCES mate_semantic_graph(id));
CREATE TABLE mate_semantic_graph_migration_plan(id VARCHAR(36) PRIMARY KEY,graph_id VARCHAR(36) NOT NULL,operation_id VARCHAR(128) NOT NULL,request_digest VARCHAR(64) NOT NULL,plan_digest VARCHAR(64) NOT NULL,status VARCHAR(24) NOT NULL,expected_graph_version BIGINT NOT NULL,source_revision_id VARCHAR(36) NOT NULL,target_revision_id VARCHAR(36) NOT NULL,source_version INT NOT NULL,target_version INT NOT NULL,source_document_digest VARCHAR(64) NOT NULL,target_document_digest VARCHAR(64) NOT NULL,source_import_lock_digest VARCHAR(64) NOT NULL,target_import_lock_digest VARCHAR(64) NOT NULL,mapping_json TEXT NOT NULL,payload_json TEXT NOT NULL,impact_json TEXT NOT NULL,approved_operation_id VARCHAR(128),approved_request_digest VARCHAR(64),executed_operation_id VARCHAR(128),executed_request_digest VARCHAR(64),rollback_operation_id VARCHAR(128),rollback_request_digest VARCHAR(64),executed_graph_version BIGINT,rollback_graph_version BIGINT,created_by VARCHAR(32) NOT NULL,approved_by VARCHAR(32),created_at TIMESTAMP NOT NULL,approved_at TIMESTAMP,executed_at TIMESTAMP,rolled_back_at TIMESTAMP,UNIQUE(graph_id,operation_id),UNIQUE(graph_id,plan_digest));
